`ok(説明, 条件)` で 1 項目。条件が `true` なら通ります。

```ts
import { describe, it, expect } from "vitest";
import { calcTax } from "./tax.js";

describe("calcTax", () => {
  it("10%を計算する", () => {
    expect(calcTax(1000, 0.1)).toBe(100);
  });

  it("端数は切り捨て", () => {
    expect(calcTax(999, 0.1)).toBe(99);
  });

  it("マイナスはエラー", () => {
    expect(() => calcTax(-1, 0.1)).toThrow();
  });
